"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 step 2c: the step 2b read-outs retrained with false labels that look like real ones (docs/iterations.md,
2026-11-20, design and predictions logged before running; the author chose to fix it).
Exploratory; local; dev for evaluation; test and replication untouched.

Why: step 2b's false labels all used the R-hear timing (scripts/p1v4_readout.py false_span: ending 0.3-1.5 s before
the line or point). On S-move the real door label is still on at the decision point (97% on dev) and the doorbell ends
about 5.6 s before it, so a label's timing still told real from false and the stop read-out kept a label cue
(scripts/p1v4_smove_diag_dev.py).

Design: everything as scripts/p1v4_readout_allclass.py (step 2b) except the false labels. Donor pool = every train
point where the family is really in the 8 s window and the detector has detections of it overlapping the window; the
pattern is all those detections (class, start, end) relative to an anchor (the point's line start if it has a line,
else the point time). Pool key (family, part, line or not), with fallbacks (family, part), (family, line or not),
(family). A false add draws a donor pattern from the key, places it at this point's anchor, gives its detections one
confidence U(0.3, 1.0), and needs at least one detection overlapping the window (up to 20 draws, else "no room").
Commands:
  edits    build the train edits (CPU), save them, and write the timing check (kept real vs added false labels)
  extract  train forward with the saved edits (GPU)
  fit      read-outs (states, ears), as step 2b
  eval     dev: natural operating points, matched-input groups (R-hear and S-move), predictions P1-P3
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout_2c.py edits|extract|fit|eval
"""
import collections
import json
import os
import random
import re
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_allclass as AC  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/grounding/allclass2c"
FAMILIES = AC.FAMILIES
SEED = 0
TRIES = 20


def part_key(r):
    if r["part"] == "floor":
        return re.search(r"_(floor[A-Za-z]+)_", r["unit"]).group(1)
    return r["part"]


def anchor(r, p):
    if p.get("line"):
        src = {s["id"]: s for s in r["sources"]}
        return src[p["line"]]["start"]
    return p["t"]


def keys_for(fam, r, p):
    pk, ln = part_key(r), bool(p.get("line"))
    return [(fam, pk, ln), (fam, pk, None), (fam, None, ln), (fam, None, None)]


def donor_pool(rows, ctx):
    """key -> (sorted gaps between anchor and point, patterns in the same order). For points with a line the gap is
    the line's length plus the 0.2 s to the point; donors are later drawn from points with a similar gap, so a label
    that is still on at the donor's point is also still on at this point (refinement logged before the extract)."""
    raw = collections.defaultdict(list)
    for r in rows:
        for p in r["points"]:
            t, k = p["t"], p["k"]
            present = {c for c, _, _ in D.window_events(r, t)}
            _, _, _, snd = ctx.point(r, k)
            a = anchor(r, p)
            for fam, classes in FAMILIES.items():
                if not any(c in present for c in classes):
                    continue
                pat = [(s[0], round(s[1] - a, 3), round(s[2] - a, 3)) for s in snd
                       if s[0] in classes and AC.overlaps(s, t)]
                if pat:
                    for key in keys_for(fam, r, p):
                        raw[key].append((round(t - a, 3), pat))
    pool = {}
    for key, v in raw.items():
        v.sort(key=lambda x: x[0])
        pool[key] = ([g for g, _ in v], [pt for _, pt in v])
    return pool


def candidates(pool, fam, r, p):
    import bisect
    gaps, pats = next(pool[k] for k in keys_for(fam, r, p) if k in pool)
    if not p.get("line"):
        return pats
    g = p["t"] - anchor(r, p)
    for tol in (0.5, 1.0):
        lo, hi = bisect.bisect_left(gaps, g - tol), bisect.bisect_right(gaps, g + tol)
        if hi > lo:
            return pats[lo:hi]
    return pats


def train_edits(rows, ctx):
    pool = donor_pool(rows, ctx)
    rng = random.Random(SEED)
    edits = {}
    log = {f: {"real dropped": 0, "false added": 0, "real conf drawn": 0, "untouched": 0, "no room": 0}
           for f in FAMILIES}
    timing = collections.defaultdict(list)           # (family, part, real|false) -> label end minus point time
    for r in rows:
        for p in r["points"]:
            pid = f"{r['unit']}|{r['version']}|{p['k']}"
            t = p["t"]
            present = {c for c, _, _ in D.window_events(r, t)}
            _, _, _, snd = ctx.point(r, p["k"])
            es = []
            for fam, classes in FAMILIES.items():
                real = any(c in present for c in classes)
                if rng.random() < 0.5:
                    if real:
                        es.append(("drop", classes, t))
                        log[fam]["real dropped"] += 1
                    else:
                        cands = candidates(pool, fam, r, p)
                        a = anchor(r, p)
                        placed = None
                        for _ in range(TRIES):
                            pat = cands[rng.randrange(len(cands))]
                            dets = [(c, round(a + s0, 3), round(a + s1, 3)) for c, s0, s1 in pat]
                            if any(s1 > t - D.WIN_S and s0 < t for _, s0, s1 in dets):
                                placed = dets
                                break
                        if placed:
                            c = round(rng.uniform(0.3, 1.0), 3)
                            es += [("add", cls, s0, s1, c) for cls, s0, s1 in placed]
                            log[fam]["false added"] += 1
                            timing[(fam, f"{part_key(r)}{' line' if p.get('line') else ''}", "false")].append(max(min(s1, t) for _, s0, s1 in placed) - t)
                        else:
                            log[fam]["no room"] += 1
                else:
                    if real:
                        es.append(("conf", classes, t, round(rng.uniform(0.3, 1.0), 3)))
                        log[fam]["real conf drawn"] += 1
                        ins = [s for s in snd if s[0] in classes and AC.overlaps(s, t)]
                        if ins:
                            timing[(fam, f"{part_key(r)}{' line' if p.get('line') else ''}", "real")].append(max(min(s[2], t) for s in ins) - t)
                    else:
                        log[fam]["untouched"] += 1
            if es:
                edits[pid] = es
    return edits, log, timing


def timing_report(timing):
    out = {}
    for fam in FAMILIES:
        for pk in sorted({k[1] for k in timing if k[0] == fam}):
            row = {}
            for kind in ("real", "false"):
                a = np.array(timing.get((fam, pk, kind), []))
                if len(a):
                    row[kind] = {"n": int(len(a)), "on_at_point": float(np.mean(a >= -0.01)),
                                 "q10": float(np.quantile(a, 0.1)), "median": float(np.median(a)),
                                 "q90": float(np.quantile(a, 0.9))}
            out[f"{fam} / {pk}"] = row
    return out


def edits_cmd():
    os.makedirs(OUT, exist_ok=True)
    rows = D.load_rows("train")
    ctx = C.Context("train")
    t0 = time.time()
    edits, log, timing = train_edits(rows, ctx)
    json.dump(edits, open(f"{OUT}/train_edits.json", "w"))
    json.dump(log, open(f"{OUT}/train_edit_counts.json", "w"), indent=1)
    rep = timing_report(timing)
    json.dump(rep, open(f"{OUT}/edit_timing_check.json", "w"), indent=1)
    print(f"edits for {len(edits)} points in {time.time() - t0:.0f} s; counts {json.dumps(log)}")
    for k, v in rep.items():
        if "real" in v and "false" in v:
            print(f"{k:24s} real n {v['real']['n']:5d} on {v['real']['on_at_point']:.2f} median {v['real']['median']:+.2f} "
                  f"| false n {v['false']['n']:5d} on {v['false']['on_at_point']:.2f} median {v['false']['median']:+.2f}")


def extract():
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    rows = D.load_rows("train")
    wins = D.windows_of(rows, "train")
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    edits = {k: [tuple(e) for e in v] for k, v in json.load(open(f"{OUT}/train_edits.json")).items()}
    ctx = AC.MultiEdited("train", edits)
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    items = []
    for w in wins:
        r = rows_by[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
        items.append({"id": w["id"], "unit": w["unit"], "path": w["path"], "text": text,
                      "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                      "gold": [-1 if w["gold"].get(q) is None else
                               int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs]})
    H, E, QW, QT, QG = [], [], [], [], []
    t0 = time.time()
    B = 8
    for i in range(0, len(items), B):
        chunk = items[i:i + B]
        waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
        h, e, qs, _ = RO.forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                        [[RO.TASK[q] for q in it["qs"]] for it in chunk])
        H.append(h.astype(np.float16))
        E.append(e.astype(np.float16))
        QW.append(qs + i)
        QT += [q for it in chunk for q in it["qs"]]
        QG += [g for it in chunk for g in it["gold"]]
        if (i // B) % 500 == 0:
            print(f"train/2c: {i + len(chunk)}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
    np.savez(f"{OUT}/feats_train_2c.npz", states=np.concatenate(H), ears=np.concatenate(E),
             q_win=np.concatenate(QW), q_task=np.array(QT), q_gold=np.array(QG),
             ids=np.array([it["id"] for it in items]), units=np.array([it["unit"] for it in items]))
    print(f"train/2c done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)


def fit():
    D.gpu_guard()
    z = dict(np.load(f"{OUT}/feats_train_2c.npz"))
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    log, models = {}, {}
    for setting in ("states", "ears"):
        X = RO.design(z, setting).astype(np.float32)
        for q in ("S", "R"):
            m = (z["q_task"] == q) & (z["q_gold"] >= 0)
            mu, sd = X[m].mean(0), X[m].std(0) + 1e-6
            Xs = ((X - mu) / sd).astype(np.float32)
            y = z["q_gold"]
            best = None
            for wd in RO.WDS:
                lin = RO.train_logreg(Xs[m & ~hold], y[m & ~hold], wd)
                p = np.clip(RO.predict(lin, Xs[m & hold]), 1e-7, 1 - 1e-7)
                yy = y[m & hold]
                ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
                log[f"{setting} {q} wd {wd}"] = ll
                print(f"2c {setting} {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
                if best is None or ll < best[0]:
                    best = (ll, wd)
            lin = RO.train_logreg(Xs[m], y[m], best[1])
            models[f"{setting}|{q}"] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                                        "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
            del Xs
    np.savez(f"{OUT}/readouts_2c.npz", **{f"{k}|{f}": v for k, d in models.items() for f, v in d.items()})
    json.dump(log, open(f"{OUT}/fit_log.json", "w"), indent=1)
    print("2c read-outs fitted:", {k: v["wd"] for k, v in models.items()}, flush=True)


def load_2c():
    z = np.load(f"{OUT}/readouts_2c.npz")
    out = {}
    for k in z.files:
        s, q, f = k.split("|")
        out.setdefault((s, q), {})[f] = z[k]
    return out


def eval_():
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    groups_map = S.load_groups("dev")
    ro = load_2c()
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    res = {"natural": {}, "matched": {}, "pairs": {}}
    th = {}
    for setting in ("states", "ears"):
        sc = RO.scores_of(zn, setting, ro)
        op = S.operating_point(rows, sc)
        th[setting] = {"S": op["th_s"], "R": op["th_r"]}
        T = S.unit_table(rows, S.decide(sc, op["th_s"], op["th_r"]), groups_map)
        m = S.metrics(T)
        res["natural"][f"2c {setting}"] = {"th": th[setting], "primary": m["primary"], "parts": m["parts"],
                                           "floors": m["floors"], "floors_met": op["floors_met"], "audio": m["audio"]}
    systems = {}
    for cond in G.CONDS:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        for setting in ("states", "ears"):
            sc = RO.scores_of(z, setting, ro)
            dec = S.decide(sc, th[setting]["S"], th[setting]["R"])
            systems.setdefault(f"2c {setting}", {})[cond] = GR.group_eval(groups, rows_by, dec, sc)
    for name, per in systems.items():
        res["matched"][name] = {}
        for part in ("r_hear", "s_move"):
            summ = {c: GR.summarise(per[c], part) for c in G.CONDS}
            mm = [summ[c] for c in G.MATCHED]
            res["matched"][name][part] = {"by_condition": summ,
                                          "mean_matched": {f: float(np.mean([x[f] for x in mm]))
                                                           for f in ("right", "conc", "follow_event", "follow_none")}}
            res["pairs"].setdefault(name, {})[part] = {
                f"conc_1_vs_{v}": float(np.mean([summ[c][f"conc_1_vs_{v}"] for c in G.MATCHED]))
                for v in ("2", "3", "4") if f"conc_1_vs_{v}" in summ[G.MATCHED[0]]}
    cl = GR.cluster_table(rows, "dev")
    crit = {}
    for part in ("r_hear", "s_move"):
        us = [g["unit"] for g in groups if g["part"] == part]
        a = np.array([np.mean([systems["2c ears"][c][u]["right"] for c in G.MATCHED]) for u in us])
        c = GR.criterion(us, cl, {}, lambda w, a=a: GR.wmean(w, a), lambda a=a: float(a.mean()))
        crit[f"grounded {part} 2c ears"] = {"point": c["point"], "ci95": c["ci95"]}
    res["grounded_with_intervals"] = crit
    ne = res["natural"]["2c ears"]
    pr = res["matched"]["2c ears"]
    p1 = pr["s_move"]["mean_matched"]["right"]
    p2, p2lo = pr["r_hear"]["mean_matched"]["right"], crit["grounded r_hear 2c ears"]["ci95"][0]
    res["predictions"] = {"P1 stop (2c ears S-move grounded >= 0.55)": [p1, p1 >= 0.55],
                          "P2 respond kept (R-hear grounded >= 0.65, lower bound > 0.50)": [[p2, p2lo],
                                                                                           p2 >= 0.65 and p2lo > 0.5],
                          "P3 no big loss (natural >= 0.934, floors met)": [ne["primary"], ne["primary"] >= 0.934
                                                                            and ne["floors_met"]]}
    res["replace_2b"] = all(v[1] for v in res["predictions"].values())
    json.dump(res, open("results/main_v04/readout_2c_dev.json", "w"), indent=1)
    for n, x in res["natural"].items():
        print(f"natural {n:9s} mean {x['primary']:.4f} audio {x['audio']:.3f} th {x['th']} floors "
              + " ".join(f"{k}:{v:.2f}" for k, v in x["floors"].items()))
    for n, x in res["matched"].items():
        for part in ("r_hear", "s_move"):
            mm = x[part]["mean_matched"]
            print(f"matched {n:9s} {part:7s} grounded {mm['right']:.3f} conc {mm['conc']:.3f} follow event "
                  f"{mm['follow_event']:.2f} none {mm['follow_none']:.2f}")
    print("pairs:", json.dumps(res["pairs"]))
    print("grounded with intervals:", json.dumps(crit))
    print("predictions:", json.dumps(res["predictions"]), "| replace 2b:", res["replace_2b"])


if __name__ == "__main__":
    {"edits": edits_cmd, "extract": extract, "fit": fit, "eval": eval_}[sys.argv[1]]()
